def merge_intervals(intervals):
    """Merge overlapping [start, end] intervals (ends inclusive)."""
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda iv: iv[0])
    merged = [list(intervals[0])]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start < last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged


def total_covered(intervals):
    """Number of integer points covered by the intervals."""
    return sum(end - start + 1 for start, end in merge_intervals(intervals))


def busiest_point(intervals):
    """The integer point covered by the most intervals (lowest on ties)."""
    counts = {}
    for start, end in intervals:
        for p in range(start, end + 1):
            counts[p] = counts.get(p, 0) + 1
    best = max(counts.values())
    return min(p for p, c in counts.items() if c == best)

