def f(xs):
    out = []
    for i, x in enumerate(xs):
        if i % 2 == 0:
            out.insert(0, x * 2)
        elif x % 3 == 0:
            out.append(x // 3)
        else:
            out[len(out) // 2:len(out) // 2] = [x, -x]
    return sum(v * (k + 1) for k, v in enumerate(out))
